function db_conn(): PDO {
    static $pdo = null;
    if ($pdo instanceof PDO) {
        return $pdo;
    }

    $databaseUrl = env_value("DATABASE_URL");
    if ($databaseUrl !== null && str_starts_with($databaseUrl, "mysql://")) {
        $parts = parse_url($databaseUrl);
        if ($parts === false) {
            throw new RuntimeException("Invalid DATABASE_URL format.");
        }
        $host = $parts["host"] ?? "127.0.0.1";
        $port = isset($parts["port"]) ? (string) $parts["port"] : "3306";
        $dbName = isset($parts["path"]) ? ltrim($parts["path"], "/") : "";
        $user = isset($parts["user"]) ? urldecode($parts["user"]) : "";
        $pass = isset($parts["pass"]) ? urldecode($parts["pass"]) : "";
        $dsn = sprintf("mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4", $host, $port, $dbName);
    } else {
        $dsn = db_dsn();
        $user = env_value("DB_USER", "");
        $pass = env_value("DB_PASS", "");
    }

    $pdo = new PDO($dsn, $user, $pass, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false,
    ]);

    return $pdo;
}

function read_env_file_value(string $path, string $targetKey): ?string {
    if (!is_file($path)) return null;
    $lines = file($path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
    if (!is_array($lines)) return null;
    foreach ($lines as $line) {
        $trim = trim($line);
        if ($trim === "" || str_starts_with($trim, "#")) continue;
        $pos = strpos($trim, "=");
        if ($pos === false) continue;
        $key = trim(substr($trim, 0, $pos));
        if ($key !== $targetKey) continue;
        $val = trim(substr($trim, $pos + 1));
        if ((str_starts_with($val, "\"") && str_ends_with($val, "\"")) || (str_starts_with($val, "'") && str_ends_with($val, "'"))) {
            $val = substr($val, 1, -1);
        }
        return $val;
    }
    return null;
}

function load_env_file(string $path, bool $overrideFileLoaded = false): void {
    if (!is_file($path)) return;
    $lines = file($path, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);
    if (!is_array($lines)) return;
    foreach ($lines as $line) {
        $trim = trim($line);
        if ($trim === "" || str_starts_with($trim, "#")) continue;
        $pos = strpos($trim, "=");
        if ($pos === false) continue;
        $key = trim(substr($trim, 0, $pos));
        $val = trim(substr($trim, $pos + 1));
        if ($key === "") continue;
        if (!preg_match('/^[A-Z_][A-Z0-9_]*$/', $key)) continue;
        if ((str_starts_with($val, "\"") && str_ends_with($val, "\"")) || (str_starts_with($val, "'") && str_ends_with($val, "'"))) {
            $val = substr($val, 1, -1);
        }
        $fromLoadedFile = ($GLOBALS["SV_ENV_FILE_KEYS"][$key] ?? false) === true;
        if (getenv($key) === false || ($overrideFileLoaded && $fromLoadedFile)) {
            putenv($key . "=" . $val);
            $_ENV[$key] = $val;
            $GLOBALS["SV_ENV_FILE_KEYS"][$key] = true;
        }
    }
}

$projectRoot = dirname(__DIR__, 2);
$baseEnvPath = $projectRoot . "/.env";
$baseEnvSelectedFile = read_env_file_value($baseEnvPath, "APP_ENV_FILE");
load_env_file($baseEnvPath);
$selectedEnvFile = $baseEnvSelectedFile
    ?? $_ENV["APP_ENV_FILE"]
    ?? getenv("APP_ENV_FILE");
if (is_string($selectedEnvFile) && $selectedEnvFile !== "") {
    $selectedEnvFile = basename($selectedEnvFile);
    putenv("APP_ENV_FILE=" . $selectedEnvFile);
    $_ENV["APP_ENV_FILE"] = $selectedEnvFile;
    $GLOBALS["SV_ENV_FILE_KEYS"]["APP_ENV_FILE"] = true;
    load_env_file($projectRoot . "/" . $selectedEnvFile, true);
}
// Hosting fallback: if APP_ENV_FILE is not set, allow a dedicated .env.host file.
if ((!is_string($selectedEnvFile) || $selectedEnvFile === "") && is_file($projectRoot . "/.env.host")) {
    load_env_file($projectRoot . "/.env.host", true);
}

function env_value(string $key, ?string $default = null): ?string {
    $value = $_ENV[$key] ?? getenv($key);
    if ($value === false || $value === null || $value === "") {
        return $default;
    }
    return (string) $value;
}

function db_dsn(): string {
    $databaseUrl = env_value("DATABASE_URL");
    if ($databaseUrl !== null) {
        return $databaseUrl;
    }

    $host = env_value("DB_HOST");
    $port = env_value("DB_PORT", "3306");
    $name = env_value("DB_NAME");
    $user = env_value("DB_USER");
    $pass = env_value("DB_PASS", "");

    if ($host === null || $name === null || $user === null) {
        throw new RuntimeException("Database is not configured. Set DB_HOST, DB_NAME, DB_USER, DB_PASS or DATABASE_URL.");
    }

    return sprintf("mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4", $host, $port, $name);
}

function account_verify_pin_reentry(array $authUser, array $body): ?array {
    $pin = (string)($body["pin"] ?? "");
    if (!auth_valid_pin($pin)) {
        return null;
    }
    $row = user_auth_row_by_id($authUser["id"]);
    if (!$row) return null;
    $ok = verify_secret($pin . ":" . (string)$row["pin_salt"], (string)$row["pin_hash"]);
    return $ok ? $row : null;
}

/**
 * GET / POST /api/auth/data-export.php
 *
 * Returns a single JSON document containing every server-side row owned by
 * the authenticated user. Streams via json_ok so the SPA can offer a
 * "Download my data" button. Does NOT include other users' data nor
 * platform-wide settings.
 */

function account_data_export(): void {
    rate_limit_guard("account_data_export", 5, 3600);
    request_log("account_data_export");
    try {
        $auth = auth_require_active_user();
    } catch (Throwable $e) {
        json_error("Unauthorized", 401, "UNAUTHORIZED");
        return;
    }
    $body = require_json_body();
    if (account_verify_pin_reentry($auth, $body) === null) {
        audit_log_action($auth["id"], $auth["role"], "ACCOUNT_DATA_EXPORT_PIN_FAILED", "user", $auth["id"], null, null);
        json_error("PIN re-entry required", 401, "PIN_REQUIRED");
        return;
    }

    $db = db_conn();

    // Profile
    $profileSt = $db->prepare(
        "SELECT id, username, display_name, role, is_active, last_login_at, created_at, updated_at,
                must_change_pin, deleted_at, deleted_reason
           FROM users WHERE id = ? LIMIT 1"
    );
    $profileSt->execute([$auth["id"]]);
    $profile = $profileSt->fetch();

    // All collection rows owned by this user (soft-deleted included so the
    // export is complete; receivers can filter on deleted_at if they want).
    $rowsSt = $db->prepare(
        "SELECT collection_name, entity_id, payload, updated_at, deleted_at, created_at
           FROM cloud_collection_rows
          WHERE user_id = ?"
    );
    $rowsSt->execute([$auth["id"]]);
    $collections = [];
    while ($row = $rowsSt->fetch()) {
        $collections[$row["collection_name"]][] = [
            "entityId" => (string)$row["entity_id"],
            "payload"  => json_decode((string)$row["payload"], true),
            "updatedAt" => $row["updated_at"],
            "deletedAt" => $row["deleted_at"],
            "createdAt" => $row["created_at"],
        ];
    }

    // Subscriptions + payments — billing trail.
    $subsSt = $db->prepare(
        "SELECT id, plan_id, status, trial_ends_at, current_period_start, current_period_end,
                cancel_at_period_end, cancelled_at, provider, provider_subscription_id,
                provider_customer_id, provider_order_id, created_at, updated_at
           FROM subscriptions WHERE user_id = ? ORDER BY id ASC"
    );
    $subsSt->execute([$auth["id"]]);
    $subscriptions = $subsSt->fetchAll();

    $paysSt = $db->prepare(
        "SELECT id, subscription_id, amount_inr, currency, expected_amount_paise,
                status, provider, provider_order_id, provider_payment_id,
                failure_reason, refund_id, paid_at, created_at, updated_at
           FROM payments WHERE user_id = ? ORDER BY id ASC"
    );
    $paysSt->execute([$auth["id"]]);
    $payments = $paysSt->fetchAll();

    // User-visible audit entries (where actor is them).
    $auditSt = $db->prepare(
        "SELECT action_key, entity_type, entity_id, ip_address, user_agent, created_at
           FROM audit_logs WHERE actor_user_id = ? ORDER BY id ASC LIMIT 5000"
    );
    try {
        $auditSt->execute([$auth["id"]]);
        $auditLogs = $auditSt->fetchAll();
    } catch (Throwable) {
        // audit_logs table may not exist in older schemas; export still succeeds.
        $auditLogs = [];
    }

    audit_log_action($auth["id"], $auth["role"], "ACCOUNT_DATA_EXPORTED", "user", $auth["id"], null, [
        "collection_count" => count($collections),
        "subscriptions"    => count($subscriptions),
        "payments"         => count($payments),
        "expires_at"       => gmdate("Y-m-d\\TH:i:s\\Z", time() + 3600),
    ]);
    user_audit_log($auth["id"], "DATA_EXPORT", "user", $auth["id"], null, [
        "collection_count" => count($collections),
        "expires_at" => gmdate("Y-m-d\\TH:i:s\\Z", time() + 3600),
    ]);

    json_ok([
        "exportVersion" => 1,
        "exportedAt"    => gmdate("Y-m-d\\TH:i:s\\Z"),
        "expiresAt"     => gmdate("Y-m-d\\TH:i:s\\Z", time() + 3600),
        "user"          => $profile ?: null,
        "collections"   => $collections,
        "subscriptions" => $subscriptions,
        "payments"      => $payments,
        "auditLogs"     => $auditLogs,
    ]);
}

/**
 * DELETE /api/auth/account.php
 *
 * Soft-delete the user, cancel any active subscription, audit-log, and
 * effectively log them out. Hard-delete via FK cascade is intentionally
 * gated to admin tooling — we keep the row marked deleted so finance can
 * reconcile billing for at least the retention window.
 *
 * Body: { pin: "1234..." [, reason?: "self"] }
 */

function account_delete(): void {
    rate_limit_guard("account_delete", 5, 3600);
    request_log("account_delete");
    try {
        $auth = auth_require_active_user();
    } catch (Throwable $e) {
        json_error("Unauthorized", 401, "UNAUTHORIZED");
        return;
    }
    $body = require_json_body();
    if (account_verify_pin_reentry($auth, $body) === null) {
        audit_log_action($auth["id"], $auth["role"], "ACCOUNT_DELETE_PIN_FAILED", "user", $auth["id"], null, null);
        json_error("PIN re-entry required", 401, "PIN_REQUIRED");
        return;
    }

    $reason = (string)($body["reason"] ?? "self");
    if (!preg_match('/^[a-z_]{3,40}$/', $reason)) $reason = "self";

    $db = db_conn();
    $db->beginTransaction();
    try {
        // Cancel active subscriptions — preserve the row for billing audit.
        $cancel = $db->prepare(
            "UPDATE subscriptions
                SET status                = IF(status IN ('active','trial','past_due','pending'), 'cancelled', status),
                    cancel_at_period_end  = 1,
                    cancelled_at          = COALESCE(cancelled_at, UTC_TIMESTAMP()),
                    updated_at            = UTC_TIMESTAMP()
              WHERE user_id = ?"
        );
        $cancel->execute([$auth["id"]]);
        $cancelledCount = $cancel->rowCount();

        // Soft-delete the user. Deactivate so any extant JWT denies on the
        // next request. The bcrypt PIN hash is zeroed so the row cannot be
        // reused to sign in even if is_active is re-enabled by an admin.
        $del = $db->prepare(
            "UPDATE users
                SET is_active       = 0,
                    deleted_at      = UTC_TIMESTAMP(),
                    deleted_reason  = ?,
                    pin_hash        = '',
                    pin_salt        = '',
                    updated_at      = UTC_TIMESTAMP()
              WHERE id = ? AND deleted_at IS NULL"
        );
        $del->execute([$reason, $auth["id"]]);
        if ($del->rowCount() === 0) {
            $db->rollBack();
            json_error("Account already deleted", 409, "ALREADY_DELETED");
            return;
        }

        audit_log_action($auth["id"], $auth["role"], "ACCOUNT_DELETED", "user", $auth["id"], null, [
            "reason"               => $reason,
            "subscriptions_closed" => $cancelledCount,
            "hard_delete_after"    => gmdate("Y-m-d\\TH:i:s\\Z", time() + 30 * 86400),
        ]);
        user_audit_log($auth["id"], "ACCOUNT_DELETION_REQUESTED", "user", $auth["id"], null, [
            "reason" => $reason,
            "subscriptionsClosed" => $cancelledCount,
            "hardDeleteAfter" => gmdate("Y-m-d\\TH:i:s\\Z", time() + 30 * 86400),
        ]);
        $db->commit();
        clear_auth_cookie();

        json_ok([
            "deleted"             => true,
            "subscriptionsClosed" => $cancelledCount,
            "hardDeleteAfter"     => gmdate("Y-m-d\\TH:i:s\\Z", time() + 30 * 86400),
            "policy"              => "soft-delete; cloud_collection_rows cascade on admin hard-delete",
        ]);
    } catch (Throwable $e) {
        $db->rollBack();
        throw $e;
    }
}

function admin_subscription_period_end_sql(string $interval): string {
    return $interval === "yearly"
        ? "DATE_ADD(UTC_TIMESTAMP(), INTERVAL 365 DAY)"
        : "DATE_ADD(UTC_TIMESTAMP(), INTERVAL 30 DAY)";
}

function admin_dashboard(): void {
    rate_limit_guard("admin_api", 120, 60);
    $admin = auth_require_admin();
    request_log("admin_dashboard", ["adminId" => $admin["id"]]);
    $db = db_conn();
    $users = (int)$db->query("SELECT COUNT(*) AS c FROM users")->fetch()["c"];
    $activeSubs = (int)$db->query("SELECT COUNT(*) AS c FROM subscriptions WHERE status = 'active'")->fetch()["c"];
    $failedPayments = (int)$db->query("SELECT COUNT(*) AS c FROM payments WHERE status = 'failed'")->fetch()["c"];
    $mrr = (string)$db->query("SELECT COALESCE(SUM(p.price_inr), 0) AS mrr FROM subscriptions s JOIN plans p ON p.id = s.plan_id WHERE s.status = 'active' AND p.billing_interval = 'monthly'")->fetch()["mrr"];
    $rateBucketCount = (int)$db->query("SELECT COUNT(*) AS c FROM api_rate_limits")->fetch()["c"];
    $recentAuditCount = (int)$db->query("SELECT COUNT(*) AS c FROM audit_logs WHERE created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 24 HOUR)")->fetch()["c"];
    $recentPayments = (int)$db->query("SELECT COUNT(*) AS c FROM payments WHERE created_at >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL 24 HOUR)")->fetch()["c"];
    json_ok([
        "users" => $users,
        "activeSubscriptions" => $activeSubs,
        "failedPayments" => $failedPayments,
        "mrrEstimateInr" => $mrr,
        "rateLimitBuckets" => $rateBucketCount,
        "recentAuditEvents24h" => $recentAuditCount,
        "payments24h" => $recentPayments,
        "actor" => $admin["username"],
    ]);
}

function admin_plans_list(): void {
    rate_limit_guard("admin_api", 120, 60);
    auth_require_admin();
    $db = db_conn();
    $st = $db->prepare("SELECT * FROM plans ORDER BY created_at DESC");
    $st->execute();
    json_ok($st->fetchAll());
}

function admin_plans_upsert(): void {
    rate_limit_guard("admin_mutation", 60, 60);
    $admin = auth_require_admin();
    request_log("admin_plans_upsert", ["adminId" => $admin["id"]]);
    $body = require_json_body();
    try {
        $id = (int)($body["id"] ?? 0);
        $code = validate_string_field($body, "code", 2, 64, '/^[A-Z0-9_]+$/');
        $name = validate_string_field($body, "name", 2, 120);
        $priceInr = validate_decimal_string((string)($body["price_inr"] ?? "0.00"), "price_inr");
        $interval = validate_enum(trim((string)($body["billing_interval"] ?? "monthly")), ["monthly", "yearly"], "billing_interval");
    } catch (InvalidArgumentException $e) {
        json_error($e->getMessage(), 422, "VALIDATION_ERROR");
        return;
    }
    $db = db_conn();
    if ($id > 0) {
        $before = $db->prepare("SELECT * FROM plans WHERE id = ? LIMIT 1");
        $before->execute([$id]);
        $old = $before->fetch() ?: null;
        $st = $db->prepare("UPDATE plans SET code = ?, name = ?, description = ?, price_inr = ?, billing_interval = ?, trial_days = ?, is_active = ?, updated_at = UTC_TIMESTAMP() WHERE id = ?");
        $st->execute([$code, $name, $body["description"] ?? null, $priceInr, $interval, (int)($body["trial_days"] ?? 0), (int)($body["is_active"] ?? 1), $id]);
        audit_log_action($admin["id"], $admin["role"], "PLAN_UPDATED", "plan", (string)$id, $old, $body);
        json_ok(["id" => $id]);
        return;
    }
    $st = $db->prepare("INSERT INTO plans (code, name, description, price_inr, billing_interval, trial_days, is_active, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, UTC_TIMESTAMP(), UTC_TIMESTAMP())");
    $st->execute([$code, $name, $body["description"] ?? null, $priceInr, $interval, (int)($body["trial_days"] ?? 0), (int)($body["is_active"] ?? 1)]);
    $newId = (int)$db->lastInsertId();
    audit_log_action($admin["id"], $admin["role"], "PLAN_CREATED", "plan", (string)$newId, null, $body);
    json_ok(["id" => $newId], 201);
}

function admin_settings_get(): void {
    rate_limit_guard("admin_api", 120, 60);
    auth_require_admin();
    json_ok(setting_get_map(false));
}

function admin_settings_put(): void {
    rate_limit_guard("admin_mutation", 60, 60);
    $admin = auth_require_admin();
    request_log("admin_settings_put", ["adminId" => $admin["id"]]);
    $body = require_json_body();
    if (count($body) === 0) {
        json_error("No settings provided", 422, "VALIDATION_ERROR");
        return;
    }
    $db = db_conn();
    foreach ($body as $key => $value) {
        if (!is_string($key) || trim($key) === "") continue;
        if (strlen($key) > 191 || preg_match('/^[a-z0-9_]+$/', $key) !== 1) continue;
        $st = $db->prepare("INSERT INTO app_settings (setting_key, setting_value, is_public, updated_by_user_id, updated_at) VALUES (?, ?, ?, ?, UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value), is_public = VALUES(is_public), updated_by_user_id = VALUES(updated_by_user_id), updated_at = UTC_TIMESTAMP()");
        $isPublic = in_array($key, ["app_title", "logo_url", "favicon_url", "support_email", "privacy_url", "terms_url", "theme_accent", "theme_primary"], true) ? 1 : 0;
        $st->execute([$key, json_encode($value, JSON_UNESCAPED_SLASHES), $isPublic, $admin["id"]]);
    }
    audit_log_action($admin["id"], $admin["role"], "BRANDING_UPDATED", "app_settings", "bulk", null, $body);
    json_ok(["updated" => true]);
}

function admin_feature_flags_get(): void {
    rate_limit_guard("admin_api", 120, 60);
    auth_require_admin();
    json_ok(flag_get_map());
}

function admin_feature_flags_put(): void {
    rate_limit_guard("admin_mutation", 60, 60);
    $admin = auth_require_admin();
    request_log("admin_feature_flags_put", ["adminId" => $admin["id"]]);
    $body = require_json_body();
    $db = db_conn();
    foreach ($body as $featureKey => $isEnabled) {
        if (!is_string($featureKey) || trim($featureKey) === "") continue;
        if (strlen($featureKey) > 191 || preg_match('/^[a-z0-9_]+$/', $featureKey) !== 1) continue;
        $st = $db->prepare("INSERT INTO feature_flags_global (feature_key, is_enabled, updated_by_user_id, updated_at) VALUES (?, ?, ?, UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE is_enabled = VALUES(is_enabled), updated_by_user_id = VALUES(updated_by_user_id), updated_at = UTC_TIMESTAMP()");
        $st->execute([$featureKey, $isEnabled ? 1 : 0, $admin["id"]]);
    }
    audit_log_action($admin["id"], $admin["role"], "FEATURE_TOGGLED", "feature_flags_global", "bulk", null, $body);
    json_ok(["updated" => true]);
}

function admin_subscription_action(): void {
    rate_limit_guard("admin_mutation", 60, 60);
    $admin = auth_require_admin();
    $body = require_json_body();
    $subscriptionId = (int)($body["subscriptionId"] ?? 0);
    $action = (string)($body["action"] ?? "");
    if ($subscriptionId <= 0 || !in_array($action, ["manual_extend", "cancel"], true)) {
        json_error("subscriptionId and valid action are required", 422, "VALIDATION_ERROR");
        return;
    }
    $db = db_conn();
    if ($action === "manual_extend") {
        $days = (int)($body["days"] ?? 0);
        if ($days <= 0 || $days > 366) {
            json_error("days must be between 1 and 366", 422, "VALIDATION_ERROR");
            return;
        }
        $st = $db->prepare(
            "UPDATE subscriptions
                SET current_period_end = DATE_ADD(COALESCE(current_period_end, UTC_TIMESTAMP()), INTERVAL ? DAY),
                    status = CASE WHEN status IN ('cancelled','expired') THEN 'active' ELSE status END,
                    updated_at = UTC_TIMESTAMP()
              WHERE id = ?"
        );
        $st->execute([$days, $subscriptionId]);
        if ($st->rowCount() === 0) {
            json_error("Subscription not found", 404, "SUBSCRIPTION_NOT_FOUND");
            return;
        }
        audit_log_action($admin["id"], $admin["role"], "SUBSCRIPTION_MANUAL_EXTEND", "subscription", (string)$subscriptionId, null, [
            "days" => $days,
            "reason" => (string)($body["reason"] ?? ""),
        ]);
        json_ok(["subscriptionId" => $subscriptionId, "extendedDays" => $days]);
        return;
    }

    $st = $db->prepare(
        "UPDATE subscriptions
            SET status = 'cancelled',
                cancel_at_period_end = 1,
                cancelled_at = UTC_TIMESTAMP(),
                updated_at = UTC_TIMESTAMP()
          WHERE id = ?"
    );
    $st->execute([$subscriptionId]);
    if ($st->rowCount() === 0) {
        json_error("Subscription not found", 404, "SUBSCRIPTION_NOT_FOUND");
        return;
    }
    audit_log_action($admin["id"], $admin["role"], "SUBSCRIPTION_ADMIN_CANCELLED", "subscription", (string)$subscriptionId, null, [
        "reason" => (string)($body["reason"] ?? ""),
    ]);
    json_ok(["subscriptionId" => $subscriptionId, "status" => "cancelled"]);
}

function admin_toggle_user_active(string $userId): void {
    rate_limit_guard("admin_mutation", 60, 60);
    $admin = auth_require_admin();
    if ($admin["id"] === $userId) {
        json_error("You cannot deactivate your own admin account", 409, "SELF_TOGGLE_BLOCKED");
        return;
    }
    $db = db_conn();
    $st = $db->prepare("UPDATE users SET is_active = CASE WHEN is_active = 1 THEN 0 ELSE 1 END, updated_at = UTC_TIMESTAMP() WHERE id = ?");
    $st->execute([$userId]);
    audit_log_action($admin["id"], $admin["role"], "USER_TOGGLED", "user", $userId, null, ["toggled" => true]);
    json_ok(["updated" => $st->rowCount() > 0]);
}

/**
 * Admin sets a user's login PIN (does not require the old PIN).
 * Forces must_change_pin when the column exists so the user rotates on next login.
 */

function admin_reset_user_pin(string $userId, string $newPin): void {
    rate_limit_guard("admin_mutation", 30, 60);
    $admin = auth_require_admin();
    if ($userId === "") {
        json_error("userId is required", 422, "VALIDATION_ERROR");
        return;
    }
    $pinError = auth_pin_validation_error($newPin);
    if ($pinError !== null) {
        json_error($pinError, 422, "VALIDATION_ERROR");
        return;
    }
    $db = db_conn();
    $u = $db->prepare("SELECT id, role FROM users WHERE id = ? LIMIT 1");
    $u->execute([$userId]);
    $user = $u->fetch();
    if (!$user) {
        json_error("User not found", 404, "USER_NOT_FOUND");
        return;
    }
    if ((string)$user["role"] === "admin" && $admin["id"] !== $userId) {
        // Allow admin to reset another admin only if explicitly same role — still OK for support.
        // Keep audit trail; do not block peer admin resets.
    }
    $nextSalt = create_pin_salt();
    $nextHash = hash_secret($newPin . ":" . $nextSalt);
    $hasMustChange = false;
    try {
        $db->query("SELECT must_change_pin FROM users LIMIT 0");
        $hasMustChange = true;
    } catch (Throwable) {
        $hasMustChange = false;
    }
    if ($hasMustChange) {
        $db->prepare(
            "UPDATE users SET pin_hash = ?, pin_salt = ?, must_change_pin = 1, updated_at = UTC_TIMESTAMP() WHERE id = ? LIMIT 1"
        )->execute([$nextHash, $nextSalt, $userId]);
    } else {
        $db->prepare(
            "UPDATE users SET pin_hash = ?, pin_salt = ?, updated_at = UTC_TIMESTAMP() WHERE id = ? LIMIT 1"
        )->execute([$nextHash, $nextSalt, $userId]);
    }
    audit_log_action($admin["id"], $admin["role"], "USER_PIN_RESET_BY_ADMIN", "user", $userId, null, [
        "mustChangePin" => $hasMustChange,
        "byAdminId" => $admin["id"],
    ]);
    json_ok(["updated" => true, "mustChangePin" => $hasMustChange]);
}

function admin_assign_plan(string $userId, int $planId): void {
    rate_limit_guard("admin_mutation", 60, 60);
    $admin = auth_require_admin();
    if ($planId <= 0) {
        json_error("planId is required", 422, "VALIDATION_ERROR");
        return;
    }
    $db = db_conn();
    $u = $db->prepare("SELECT id FROM users WHERE id = ? LIMIT 1");
    $u->execute([$userId]);
    if (!$u->fetch()) {
        json_error("User not found", 404, "USER_NOT_FOUND");
        return;
    }
    $p = $db->prepare("SELECT id, billing_interval FROM plans WHERE id = ? AND is_active = 1 LIMIT 1");
    $p->execute([$planId]);
    $plan = $p->fetch();
    if (!$plan) {
        json_error("Plan not found", 404, "PLAN_NOT_FOUND");
        return;
    }
    $db->beginTransaction();
    try {
        $db->prepare("UPDATE subscriptions SET status = 'cancelled', updated_at = UTC_TIMESTAMP() WHERE user_id = ? AND status IN ('pending','active','past_due')")
            ->execute([$userId]);
        $periodEndSql = admin_subscription_period_end_sql((string)$plan["billing_interval"]);
        $db->prepare("INSERT INTO subscriptions (user_id, plan_id, status, provider, current_period_start, current_period_end, created_at, updated_at) VALUES (?, ?, 'active', 'razorpay', UTC_TIMESTAMP(), {$periodEndSql}, UTC_TIMESTAMP(), UTC_TIMESTAMP())")
            ->execute([$userId, $planId]);
        $subscriptionId = (int)$db->lastInsertId();
        $db->commit();
        audit_log_action($admin["id"], $admin["role"], "USER_PLAN_ASSIGNED", "subscription", (string)$subscriptionId, null, ["userId" => $userId, "planId" => $planId]);
        json_ok(["subscriptionId" => $subscriptionId]);
    } catch (Throwable $e) {
        $db->rollBack();
        throw $e;
    }
}

function auth_throttle_status_safe(string $username, string $ip): array {
    try {
        return login_throttle_status($username, $ip);
    } catch (Throwable $e) {
        return ["blocked" => false, "attempts" => 0];
    }
}

function auth_record_failure_safe(string $username, string $ip): void {
    try {
        record_login_failure($username, $ip);
    } catch (Throwable $e) {
        // Best-effort: auth must not crash if throttle storage is unavailable.
    }
}

function auth_clear_failures_safe(string $username, string $ip): void {
    try {
