function login_throttle_status(string $username, string $ipAddress): array {
    $db = db_conn();
    $st = $db->prepare("SELECT attempt_count, locked_until FROM login_attempts WHERE username = ? AND ip_address = ? LIMIT 1");
    $st->execute([$username, $ipAddress]);
    $row = $st->fetch();
    if (!$row) {
        return ["blocked" => false, "attempts" => 0];
    }
    $lockedUntil = $row["locked_until"];
    if (is_string($lockedUntil) && $lockedUntil !== "" && strtotime($lockedUntil) > time()) {
        return ["blocked" => true, "attempts" => (int)$row["attempt_count"], "lockedUntil" => $lockedUntil];
    }
    return ["blocked" => false, "attempts" => (int)$row["attempt_count"]];
}

function record_login_failure(string $username, string $ipAddress): void {
    $db = db_conn();
    $status = login_throttle_status($username, $ipAddress);
    $nextCount = ((int)($status["attempts"] ?? 0)) + 1;
    $lockSeconds = $nextCount >= 5 ? min(1800, ($nextCount - 4) * 120) : 0;
    $lockedUntil = $lockSeconds > 0 ? gmdate("Y-m-d H:i:s", time() + $lockSeconds) : null;
    $st = $db->prepare(
        "INSERT INTO login_attempts (username, ip_address, attempt_count, locked_until, updated_at, created_at)
         VALUES (?, ?, ?, ?, UTC_TIMESTAMP(), UTC_TIMESTAMP())
         ON DUPLICATE KEY UPDATE attempt_count = VALUES(attempt_count), locked_until = VALUES(locked_until), updated_at = UTC_TIMESTAMP()"
    );
    $st->execute([$username, $ipAddress, $nextCount, $lockedUntil]);
}

function clear_login_failures(string $username, string $ipAddress): void {
    $db = db_conn();
    $st = $db->prepare("DELETE FROM login_attempts WHERE username = ? AND ip_address = ?");
    $st->execute([$username, $ipAddress]);
}

function billing_renewal_start(?string $currentPeriodEndUtc): string {
    $now = time();
    $endTs = is_string($currentPeriodEndUtc) ? strtotime($currentPeriodEndUtc) : false;
    $start = $endTs && $endTs > $now ? $endTs : $now;
    return gmdate("Y-m-d H:i:s", $start);
}

function billing_period_end_sql(string $interval, string $startUtc): string {
    // Returns a SQL expression that adds the interval to a literal datetime.
    // We do this server-side rather than via INTERVAL on column because the
    // base may be either now() (free renewal) or previous_period_end (fair).
    $days = ($interval === "yearly") ? 365 : 30;
    return sprintf("DATE_ADD('%s', INTERVAL %d DAY)", $startUtc, $days);
}

/**
 * Look up the active price for a plan at a given time. Falls back to plans.price_inr.
 */

function billing_active_price_paise(int $planId, string $atUtc = "now"): int {
    $db = db_conn();
    $when = gmdate("Y-m-d H:i:s", $atUtc === "now" ? time() : (int)strtotime($atUtc));
    try {
        $st = $db->prepare(
            "SELECT amount_paise FROM plan_prices
              WHERE plan_id = ? AND starts_at <= ? AND (ends_at IS NULL OR ends_at > ?)
              ORDER BY starts_at DESC LIMIT 1"
        );
        $st->execute([$planId, $when, $when]);
        $row = $st->fetch();
        if ($row && (int)$row["amount_paise"] > 0) return (int)$row["amount_paise"];
    } catch (Throwable) {
        // plan_prices table may not be present pre-migration
    }
    $st = $db->prepare("SELECT price_inr FROM plans WHERE id = ? LIMIT 1");
    $st->execute([$planId]);
    $row = $st->fetch();
    if (!$row) throw new RuntimeException("Unknown plan id {$planId}");
    return cloud_parse_money_input_to_paise($row["price_inr"], "price_inr", true, false);
}

/**
 * Effective numeric quotas for a user's active plan. Returns associative array,
 * e.g. ["max_transactions_per_month" => 500].
 */

function billing_user_quotas(string $userId): array {
    $db = db_conn();
    $st = $db->prepare(
        "SELECT pf.feature_key, pf.limit_value, pf.limit_unit
           FROM (
                SELECT plan_id
                  FROM subscriptions
                 WHERE user_id = ? AND status IN ('active','trial')
                 ORDER BY id DESC
                 LIMIT 1
           ) s
           JOIN plan_features pf ON pf.plan_id = s.plan_id
          WHERE pf.limit_value IS NOT NULL"
    );
    try {
        $st->execute([$userId]);
    } catch (Throwable) {
        return []; // pre-migration
    }
    $out = [];
    while ($row = $st->fetch()) {
        $out[$row["feature_key"]] = [
            "value" => $row["limit_value"] !== null ? (int)$row["limit_value"] : null,
            "unit"  => $row["limit_unit"],
        ];
    }
    return $out;
}

/**
 * Quick: is `feature_key` enabled (boolean) for this user's plan?
 */

function billing_user_has_feature(string $userId, string $featureKey): bool {
    $db = db_conn();
    $st = $db->prepare(
        "SELECT pf.is_enabled
           FROM subscriptions s
           JOIN plan_features pf ON pf.plan_id = s.plan_id
          WHERE s.user_id = ? AND s.status IN ('active','trial') AND pf.feature_key = ?
          ORDER BY s.id DESC LIMIT 1"
    );
    $st->execute([$userId, $featureKey]);
    $row = $st->fetch();
    return $row && (int)$row["is_enabled"] === 1;
}

function cloud_max_row_payload_bytes(): int {
    return 65536;
}

/** Max raw HTTP body for POST /api/cloud/sync/push (bytes). */

function cloud_max_sync_push_body_bytes(): int {
    return 4194304; // 4 MiB
}

/** Default max for generic JSON entity routes (bytes). */

function cloud_max_entity_json_body_bytes(): int {
    return 1048576; // 1 MiB
}

/**
 * Allowed cloud collection_name values (strict allowlist).
 * Unknown names are rejected on sync push; entity routes use is_cloud_collection().
 */

function cloud_collection_allowlist(): array {
    static $allowlist = null;
    if ($allowlist !== null) {
        return $allowlist;
    }

    $bundlePath = __DIR__ . "/../config/syncContracts.generated.json";
    $sourcePath = dirname(__DIR__, 2) . "/src/config/syncContracts.generated.json";
    $path = is_file($bundlePath) ? $bundlePath : $sourcePath;
    $raw = is_file($path) ? file_get_contents($path) : false;
    if ($raw === false) {
        throw new RuntimeException("Sync contract registry missing");
    }
    $decoded = json_decode($raw, true);
    if (!is_array($decoded) || !isset($decoded["contracts"]) || !is_array($decoded["contracts"])) {
        throw new RuntimeException("Sync contract registry is invalid");
    }

    $list = [];
    foreach ($decoded["contracts"] as $contract) {
        if (!is_array($contract)) {
            continue;
        }
        $name = $contract["serverAllowlistName"] ?? null;
        if (is_string($name) && $name !== "") {
            $list[] = $name;
        }
    }
    $allowlist = array_values(array_unique($list));
    sort($allowlist);
    return $allowlist;
}

function cloud_is_allowed_collection(string $name): bool {
    return in_array($name, cloud_collection_allowlist(), true);
}

function cloud_validate_encoded_payload_size(string $json, ?string $context = null): void {
    $len = strlen($json);
    $max = cloud_max_row_payload_bytes();
    if ($len > $max) {
        $ctx = $context !== null ? " ({$context})" : "";
        throw new InvalidArgumentException("Payload exceeds {$max} bytes{$ctx}");
    }
}

function cloud_validate_sync_push_raw_size(string $raw): void {
    if (strlen($raw) > cloud_max_sync_push_body_bytes()) {
        throw new InvalidArgumentException("Sync push body exceeds maximum allowed size");
    }
}

function cloud_assert_entity_user_id(string $authUserId, array $entity): void {
    $uid = $entity["userId"] ?? null;
    if (!is_string($uid) || $uid === "" || $uid !== $authUserId) {
        throw new InvalidArgumentException("userId must match authenticated user");
    }
}

/** @return array<string, mixed> SQL column => value (nullable) */

function cloud_ccr_compute_indexed(string $collection, array $entity, string $payloadJson): array {
    $schemaVersion = isset($entity["schemaVersion"]) && is_numeric($entity["schemaVersion"])
        ? (int)$entity["schemaVersion"]
        : 1;
    if ($schemaVersion < 1) {
        $schemaVersion = 1;
    }

    $amountPaise = cloud_entity_primary_amount_paise($collection, $entity);
    $payloadHash = hash("sha256", $payloadJson, false);

    $srcDev = $entity["sourceDeviceId"] ?? null;
    $sourceDeviceId = is_string($srcDev) && strlen($srcDev) <= 191 ? $srcDev : null;

    $txnLocalDate = null;
    $txnMonth = null;
    $txnType = null;
    $paymentMode = null;
    $categoryId = null;
    $accountId = null;
    $cardId = null;
    $loanId = null;
    $goalId = null;
    $udhariId = null;
    $businessOrPersonal = null;

    if ($collection === "transactions") {
        $dateRaw = $entity["date"] ?? null;
        if (is_string($dateRaw) && trim($dateRaw) !== "") {
            $ts = strtotime($dateRaw);
            if ($ts !== false) {
                $txnLocalDate = gmdate("Y-m-d", $ts);
                $txnMonth = substr($txnLocalDate, 0, 7);
            }
        }
        $t = $entity["type"] ?? null;
        $txnType = is_string($t) ? substr($t, 0, 32) : null;
        $pm = $entity["paymentMode"] ?? null;
        $paymentMode = is_string($pm) ? substr($pm, 0, 32) : null;

        $cid = $entity["categoryId"] ?? null;
        $categoryId = is_string($cid) && $cid !== "" ? substr($cid, 0, 191) : null;
        $aid = $entity["accountId"] ?? null;
        $accountId = is_string($aid) && $aid !== "" ? substr($aid, 0, 191) : null;
        $cardId = cloud_str_id($entity["linkedCardId"] ?? null);
        $loanId = cloud_str_id($entity["linkedLoanId"] ?? null);
        $goalId = cloud_str_id($entity["linkedGoalId"] ?? null);
        $udhariId = cloud_str_id($entity["linkedUdhariId"] ?? null);

        $bop = $entity["businessOrPersonal"] ?? null;
        $businessOrPersonal = is_string($bop) ? substr($bop, 0, 32) : null;
    }

    return [
        "schema_version" => $schemaVersion,
        "amount_paise" => $amountPaise,
        "txn_local_date" => $txnLocalDate,
        "txn_month" => $txnMonth,
        "txn_type" => $txnType,
        "payment_mode" => $paymentMode,
        "category_id" => $categoryId,
        "account_id" => $accountId,
        "card_id" => $cardId,
        "loan_id" => $loanId,
        "goal_id" => $goalId,
        "udhari_id" => $udhariId,
        "business_or_personal" => $businessOrPersonal,
        "source_device_id" => $sourceDeviceId,
        "payload_hash" => $payloadHash,
    ];
}

function cloud_str_id($v): ?string {
    if (!is_string($v) || $v === "") {
        return null;
    }
    return substr($v, 0, 191);
}

function cloud_validate_transaction_payload(string $authUserId, array &$entity): void {
    cloud_assert_entity_user_id($authUserId, $entity);

    if (((int)($entity["isDeleted"] ?? 0)) === 1) {
        return;
    }

    if (!isset($entity["businessOrPersonal"])) {
        $entity["businessOrPersonal"] = "personal";
    }
    if (!isset($entity["needWant"])) {
        $entity["needWant"] = "unassigned";
    }
    if (!isset($entity["fixedVariable"])) {
        $entity["fixedVariable"] = "unassigned";
    }
    if (!isset($entity["plannedUnplanned"])) {
        $entity["plannedUnplanned"] = "unassigned";
    }

    $id = $entity["id"] ?? null;
    if (!is_string($id) || trim($id) === "") {
        throw new InvalidArgumentException("Transaction id is required");
    }

    $type = $entity["type"] ?? null;
    if (!is_string($type) || !in_array($type, cloud_transaction_types(), true)) {
        throw new InvalidArgumentException("Invalid transaction type");
    }

    $amountPaise = null;
    if (array_key_exists("amountPaise", $entity) && $entity["amountPaise"] !== null) {
        $rawAp = $entity["amountPaise"];
        if (is_bool($rawAp)) {
            throw new InvalidArgumentException("amountPaise must be numeric");
        }
        if (is_int($rawAp)) {
            $amountPaise = $rawAp;
        } elseif (is_string($rawAp) && preg_match('/^\d+$/', $rawAp) === 1) {
            $amountPaise = (int)$rawAp;
        } elseif (is_float($rawAp) && is_finite($rawAp) && floor($rawAp) == $rawAp) {
            $amountPaise = (int)$rawAp;
        } else {
            throw new InvalidArgumentException("amountPaise must be a positive integer");
        }
        if ($amountPaise < 1) {
            throw new InvalidArgumentException("amountPaise must be a positive integer");
        }
    }
    if ($amountPaise !== null) {
        // ok
        $entity["amountPaise"] = $amountPaise;
    } elseif (array_key_exists("amount", $entity)) {
        $amountPaise = cloud_parse_money_input_to_paise($entity["amount"], "amount", false, true);
        $entity["amountPaise"] = $amountPaise;
    } else {
        throw new InvalidArgumentException("amountPaise or amount is required");
    }

    $dateRaw = $entity["date"] ?? null;
    if (!is_string($dateRaw) || trim($dateRaw) === "") {
        throw new InvalidArgumentException("date is required");
    }
    if (strtotime($dateRaw) === false) {
        throw new InvalidArgumentException("date is invalid");
    }

    $pm = $entity["paymentMode"] ?? null;
    if (!is_string($pm) || !in_array($pm, cloud_transaction_payment_modes(), true)) {
        throw new InvalidArgumentException("Invalid paymentMode");
    }

    $typesNeedCategory = ["income", "expense", "refund", "udhari_write_off"];
    if (in_array($type, $typesNeedCategory, true)) {
        $cat = $entity["categoryId"] ?? null;
        if (!is_string($cat) || trim($cat) === "") {
            throw new InvalidArgumentException("categoryId is required for this transaction type");
        }
    }

    if (($type === "expense" || $type === "refund") && $pm === "credit_card") {
        $lc = $entity["linkedCardId"] ?? null;
        if (!is_string($lc) || trim($lc) === "") {
            throw new InvalidArgumentException("linkedCardId is required for credit card expenses/refunds");
        }
    }

    $cashLikeModes = ["cash", "upi", "bank_transfer", "debit_card", "cheque", "wallet", "auto_debit", "other"];
    if (($type === "expense" || $type === "refund") && in_array($pm, $cashLikeModes, true)) {
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for this payment mode");
        }
    }

    if (in_array($type, ["emi_payment", "loan_disbursement"], true)) {
        $ll = $entity["linkedLoanId"] ?? null;
        if (!is_string($ll) || trim($ll) === "") {
            throw new InvalidArgumentException("linkedLoanId is required for this transaction type");
        }
    }

    if ($type === "emi_payment") {
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for emi_payment");
        }
    }

    if ($type === "loan_disbursement") {
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for loan_disbursement");
        }
    }

    if ($type === "cc_payment") {
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for cc_payment");
        }
        $lc = $entity["linkedCardId"] ?? null;
        if (!is_string($lc) || trim($lc) === "") {
            throw new InvalidArgumentException("linkedCardId is required for cc_payment");
        }
    }

    if ($type === "savings_contribution") {
        $lg = $entity["linkedGoalId"] ?? null;
        if (!is_string($lg) || trim($lg) === "") {
            throw new InvalidArgumentException("linkedGoalId is required for savings_contribution");
        }
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for savings_contribution");
        }
    }

    if ($type === "investment_contribution") {
        $inv = $entity["linkedSavingsId"] ?? null;
        if (!is_string($inv) || trim($inv) === "") {
            throw new InvalidArgumentException("linkedSavingsId is required for investment_contribution");
        }
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for investment_contribution");
        }
    }

    if ($type === "udhari_given" || $type === "udhari_received" || $type === "udhari_collect" || $type === "udhari_repay") {
        $ud = $entity["linkedUdhariId"] ?? null;
        if (!is_string($ud) || trim($ud) === "") {
            throw new InvalidArgumentException("linkedUdhariId is required for udhari transactions");
        }
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for udhari transactions");
        }
        $person = $entity["merchantOrPerson"] ?? null;
        if (!is_string($person) || trim($person) === "") {
            throw new InvalidArgumentException("merchantOrPerson is required for udhari transactions");
        }
    }

    if ($type === "udhari_write_off") {
        $ud = $entity["linkedUdhariId"] ?? null;
        if (!is_string($ud) || trim($ud) === "") {
            throw new InvalidArgumentException("linkedUdhariId is required for udhari_write_off");
        }
        $cat = $entity["categoryId"] ?? null;
        if (!is_string($cat) || trim($cat) === "") {
            throw new InvalidArgumentException("categoryId is required for udhari_write_off");
        }
    }

    if ($type === "income" || $type === "refund") {
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for this transaction type");
        }
    }

    if ($type === "adjustment") {
        $acc = $entity["accountId"] ?? null;
        if (!is_string($acc) || trim($acc) === "") {
            throw new InvalidArgumentException("accountId is required for adjustment");
        }
    }

    if ($type === "transfer") {
        $from = $entity["accountId"] ?? null;
        $to = $entity["toAccountId"] ?? null;
        if (!is_string($from) || trim($from) === "" || !is_string($to) || trim($to) === "") {
            throw new InvalidArgumentException("transfer requires accountId and toAccountId");
        }
        if ($from === $to) {
            throw new InvalidArgumentException("transfer from and to account must differ");
        }
    }

    $bop = $entity["businessOrPersonal"] ?? "personal";
    if (!is_string($bop) || !in_array($bop, ["personal", "business", "mixed"], true)) {
        throw new InvalidArgumentException("businessOrPersonal must be personal, business, or mixed");
    }

    $nw = $entity["needWant"] ?? "unassigned";
    if (!is_string($nw) || !in_array($nw, ["need", "want", "luxury", "unassigned"], true)) {
        throw new InvalidArgumentException("needWant must be need, want, luxury, or unassigned");
    }

    $fv = $entity["fixedVariable"] ?? "unassigned";
    if (!is_string($fv) || !in_array($fv, ["fixed", "variable", "unassigned"], true)) {
        throw new InvalidArgumentException("fixedVariable must be fixed, variable, or unassigned");
    }

    $pu = $entity["plannedUnplanned"] ?? "unassigned";
    if (!is_string($pu) || !in_array($pu, ["planned", "unplanned", "unassigned"], true)) {
        throw new InvalidArgumentException("plannedUnplanned must be planned, unplanned, or unassigned");
    }
}

function cloud_validate_entity_for_collection(string $authUserId, string $collection, array &$entity): void {
    cloud_assert_entity_user_id($authUserId, $entity);
    if ($collection === "transactions") {
        cloud_validate_transaction_payload($authUserId, $entity);
    }
}

/** Column list for INSERT / ON DUPLICATE KEY UPDATE (matches migration phase_04). */

function cloud_ccr_indexed_column_sql(): string {
    return "schema_version, amount_paise, txn_local_date, txn_month, txn_type, payment_mode, "
        . "category_id, account_id, card_id, loan_id, goal_id, udhari_id, business_or_personal, "
        . "source_device_id, payload_hash";
}

function cloud_ccr_upsert_on_duplicate_sql(): string {
    $parts = [];
    foreach (explode(", ", cloud_ccr_indexed_column_sql()) as $c) {
        $parts[] = "{$c} = VALUES({$c})";
    }
    return "payload = VALUES(payload), updated_at = VALUES(updated_at), deleted_at = VALUES(deleted_at), "
        . implode(", ", $parts);
}

/**
 * @return array{0: string, 1: array<int, mixed>} SQL with placeholders + execute params
 */

function cloud_ccr_build_upsert(string $authUserId, string $collection, string $entityId, array $entity, string $updatedDateSql, ?string $deletedAtSql, string $newRowPkId): array {
    $payloadJson = encode_payload($entity);
    cloud_validate_encoded_payload_size($payloadJson, $collection . "/" . $entityId);
    $idx = cloud_ccr_compute_indexed($collection, $entity, $payloadJson);
    $indexedCols = cloud_ccr_indexed_column_sql();
    $dup = cloud_ccr_upsert_on_duplicate_sql();
    $sql = "INSERT INTO cloud_collection_rows (id, user_id, collection_name, entity_id, payload, updated_at, deleted_at, {$indexedCols})
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE {$dup}";
    $params = [
        $newRowPkId,
        $authUserId,
        $collection,
        $entityId,
        $payloadJson,
        $updatedDateSql,
        $deletedAtSql,
        $idx["schema_version"],
        $idx["amount_paise"],
        $idx["txn_local_date"],
        $idx["txn_month"],
        $idx["txn_type"],
        $idx["payment_mode"],
        $idx["category_id"],
        $idx["account_id"],
        $idx["card_id"],
        $idx["loan_id"],
        $idx["goal_id"],
        $idx["udhari_id"],
        $idx["business_or_personal"],
        $idx["source_device_id"],
        $idx["payload_hash"],
    ];
    return [$sql, $params];
}

/**
 * @return array{0: string, 1: array<int, mixed>}
 */

function cloud_ccr_build_update_by_table_id(array $entity, string $collection, string $updatedDateSql, ?string $deletedAtSql, string $tableRowId): array {
    $payloadJson = encode_payload($entity);
    $entityId = (string)($entity["id"] ?? "");
    cloud_validate_encoded_payload_size($payloadJson, $collection . "/" . $entityId);
    $idx = cloud_ccr_compute_indexed($collection, $entity, $payloadJson);
    $sql = "UPDATE cloud_collection_rows SET payload = ?, updated_at = ?, deleted_at = ?, schema_version = ?, amount_paise = ?, "
        . "txn_local_date = ?, txn_month = ?, txn_type = ?, payment_mode = ?, category_id = ?, account_id = ?, "
        . "card_id = ?, loan_id = ?, goal_id = ?, udhari_id = ?, business_or_personal = ?, source_device_id = ?, payload_hash = ? "
        . "WHERE id = ?";
    $params = [
        $payloadJson,
        $updatedDateSql,
        $deletedAtSql,
        $idx["schema_version"],
        $idx["amount_paise"],
        $idx["txn_local_date"],
        $idx["txn_month"],
        $idx["txn_type"],
        $idx["payment_mode"],
        $idx["category_id"],
        $idx["account_id"],
        $idx["card_id"],
        $idx["loan_id"],
        $idx["goal_id"],
        $idx["udhari_id"],
        $idx["business_or_personal"],
        $idx["source_device_id"],
        $idx["payload_hash"],
        $tableRowId,
    ];
    return [$sql, $params];
}

function fe_amount_paise(array $tx): int {
    if (isset($tx["amountPaise"]) && is_numeric($tx["amountPaise"])) {
        return (int)$tx["amountPaise"];
    }
    if (array_key_exists("amount", $tx)) {
        return cloud_parse_money_input_to_paise($tx["amount"], "amount");
    }
    return 0;
}

/** @return array<string, array> keyed by EMIPayment.transactionId */

function fe_emis_by_transaction_id(PDO $db, string $userId): array {
    $st = $db->prepare(
        "SELECT entity_id, payload FROM cloud_collection_rows
         WHERE user_id = ? AND collection_name = 'emis' AND deleted_at IS NULL",
    );
    $st->execute([$userId]);
    $map = [];
    while ($r = $st->fetch()) {
        $p = decode_payload($r["payload"]);
        $tid = $p["transactionId"] ?? null;
        if (is_string($tid) && $tid !== "") {
            $map[$tid] = $p;
        }
    }
    return $map;
}

function fe_event_id_for_transaction(string $txnId): string {
    return "fevt_" . $txnId;
}

/** Remove posted effects; keep the financial_events row for audit when possible. */

function fe_clear_effects_for_event(PDO $db, string $eventId): void {
    $st = $db->prepare("DELETE FROM financial_effects WHERE event_id = ?");
    $st->execute([$eventId]);
}

/** Transaction removed or invalid amount — void ledger (effects cleared; event soft-deleted). */

function fe_void_ledger_for_transaction(PDO $db, string $userId, string $txnId): void {
    $eid = fe_event_id_for_transaction($txnId);
    fe_clear_effects_for_event($db, $eid);
    $now = gmdate("Y-m-d H:i:s");
    $st = $db->prepare(
        "UPDATE financial_events SET deleted_at = ?, status = 'reversed', updated_at = ? WHERE user_id = ? AND id = ? AND deleted_at IS NULL",
    );
    $st->execute([$now, $now, $userId, $eid]);
}

/**
 * Replace effects and upsert the active posted row for this transaction (edit = reverse old effects + new effects).
 */

function fe_upsert_posted_ledger(
    PDO $db,
    string $userId,
    string $txnId,
    string $eventType,
    string $eventDate,
    int $amt,
    string $desc,
    string $status,
    string $now,
    array $effects,
): void {
    $eid = fe_event_id_for_transaction($txnId);
    fe_clear_effects_for_event($db, $eid);

    $sel = $db->prepare("SELECT id FROM financial_events WHERE id = ? AND user_id = ?");
    $sel->execute([$eid, $userId]);
    if ($sel->fetch()) {
        $up = $db->prepare(
            "UPDATE financial_events SET source_transaction_id = ?, event_type = ?, event_date = ?, amount_paise = ?, description = ?, status = ?, deleted_at = NULL, reversal_of_event_id = NULL, updated_at = ? WHERE id = ? AND user_id = ?",
        );
        $up->execute([$txnId, $eventType, $eventDate, $amt, $desc, $status, $now, $eid, $userId]);
    } else {
        $insEv = $db->prepare(
            "INSERT INTO financial_events (id, user_id, source_transaction_id, event_type, event_date, amount_paise, currency, description, source, status, reversal_of_event_id, created_at, updated_at, deleted_at)
             VALUES (?, ?, ?, ?, ?, ?, 'INR', ?, 'transaction', ?, NULL, ?, ?, NULL)",
        );
        $insEv->execute([$eid, $userId, $txnId, $eventType, $eventDate, $amt, $desc, $status, $now, $now]);
    }

    $insFx = $db->prepare(
        "INSERT INTO financial_effects (id, event_id, user_id, target_type, target_id, effect_direction, amount_paise, component, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
    );
    foreach ($effects as $fx) {
        $insFx->execute([
            $fx["id"],
            $fx["event_id"],
            $fx["user_id"],
            $fx["target_type"],
            $fx["target_id"],
            $fx["effect_direction"],
            $fx["amount_paise"],
            $fx["component"],
            $fx["created_at"],
        ]);
    }
}

function fe_principal_interest_paise(array $emi, int $totalPaise): array {
    $pp = isset($emi["principalComponentPaise"]) && is_numeric($emi["principalComponentPaise"])
        ? (int)$emi["principalComponentPaise"]
        : (array_key_exists("principalComponent", $emi)
            ? cloud_parse_money_input_to_paise($emi["principalComponent"], "principalComponent")
            : 0);
    $ip = isset($emi["interestComponentPaise"]) && is_numeric($emi["interestComponentPaise"])
        ? (int)$emi["interestComponentPaise"]
        : (array_key_exists("interestComponent", $emi)
            ? cloud_parse_money_input_to_paise($emi["interestComponent"], "interestComponent")
            : 0);
    $s = $pp + $ip;
    if ($s > 0 && $s !== $totalPaise) {
        $pp = (int)round($totalPaise * $pp / $s);
        $ip = $totalPaise - $pp;
    }
    return [$pp, $ip];
}

function fe_int_paise(array $row, string $paiseField, string $legacyField): int {
    if (isset($row[$paiseField]) && is_numeric($row[$paiseField])) {
        return (int)$row[$paiseField];
    }
    if (array_key_exists($legacyField, $row)) {
        return cloud_parse_money_input_to_paise($row[$legacyField], $legacyField);
    }
    return 0;
}

/**
 * Build + persist ledger for one transaction row (assoc array, camelCase keys).
 */

function finance_events_sync_transaction(PDO $db, string $userId, array $tx): void {
    $txnId = isset($tx["id"]) && is_string($tx["id"]) ? $tx["id"] : "";
    if ($txnId === "" || (($tx["isDeleted"] ?? 0) === 1 || ($tx["isDeleted"] ?? false) === true)) {
        if ($txnId !== "") {
            fe_void_ledger_for_transaction($db, $userId, $txnId);
        }
        return;
    }

    $amt = fe_amount_paise($tx);
    if ($amt < 1) {
        fe_void_ledger_for_transaction($db, $userId, $txnId);
        return;
    }

    $emisByTxn = fe_emis_by_transaction_id($db, $userId);
    $eventId = "fevt_" . $txnId;
    $now = gmdate("Y-m-d H:i:s");
    $dateRaw = $tx["date"] ?? "";
    $eventDate = is_string($dateRaw) && strtotime($dateRaw) !== false
        ? gmdate("Y-m-d", strtotime($dateRaw))
        : gmdate("Y-m-d");

    $type = (string)($tx["type"] ?? "");
    $pm = (string)($tx["paymentMode"] ?? "");
    $status = "posted";
    $eventType = "adjustment";
    $effects = [];
    $reasons = [];

    $pushReason = function (string $code) use (&$status, &$reasons): void {
        $status = "needs_review";
        $reasons[] = $code;
    };

    $addFx = function (
        string $targetType,
        string $targetId,
        string $dir,
        int $paise,
        string $component,
    ) use (&$effects, $eventId, $userId, $now): void {
        $effects[] = [
            "id" => uid("fef"),
            "event_id" => $eventId,
            "user_id" => $userId,
            "target_type" => $targetType,
            "target_id" => $targetId,
            "effect_direction" => $dir,
            "amount_paise" => $paise,
            "component" => $component,
            "created_at" => $now,
        ];
    };

    if ($type === "expense") {
        if ($pm === "credit_card") {
            $eventType = "credit_card_purchase";
            $cid = $tx["linkedCardId"] ?? null;
            if (!is_string($cid) || $cid === "") {
                $pushReason("MISSING_CARD");
            } else {
                $addFx("credit_card", $cid, "increase", $amt, "liability");
            }
            $cat = $tx["categoryId"] ?? null;
            if (is_string($cat) && $cat !== "") {
                $addFx("expense_category", $cat, "increase", $amt, "expense");
            } else {
                $pushReason("MISSING_CATEGORY");
            }
        } else {
            $eventType = "expense";
            $acc = $tx["accountId"] ?? null;
            if (is_string($acc) && $acc !== "") {
                $addFx("account", $acc, "decrease", $amt, "cash");
            } else {
                $pushReason("MISSING_ACCOUNT");
            }
            $cat = $tx["categoryId"] ?? null;
            if (is_string($cat) && $cat !== "") {
                $addFx("expense_category", $cat, "increase", $amt, "expense");
            } else {
                $pushReason("MISSING_CATEGORY");
            }
        }
    } elseif ($type === "income") {
        $eventType = "income";
        $acc = $tx["accountId"] ?? null;
        if (is_string($acc) && $acc !== "") {
            $addFx("account", $acc, "increase", $amt, "cash");
        } else {
            $pushReason("MISSING_ACCOUNT");
        }
        $cat = $tx["categoryId"] ?? null;
        if (is_string($cat) && $cat !== "") {
            $addFx("income_category", $cat, "increase", $amt, "income");
        } else {
            $pushReason("MISSING_CATEGORY");
        }
    } elseif ($type === "refund") {
        $eventType = "refund";
        if ($pm === "credit_card") {
            $cid = $tx["linkedCardId"] ?? null;
            if (is_string($cid) && $cid !== "") {
                $addFx("credit_card", $cid, "decrease", $amt, "liability");
            } else {
                $pushReason("MISSING_CARD");
            }
            $cat = $tx["categoryId"] ?? null;
            if (is_string($cat) && $cat !== "") {
                $addFx("expense_category", $cat, "decrease", $amt, "expense");
            } else {
                $pushReason("MISSING_CATEGORY");
            }
        } else {
            $acc = $tx["accountId"] ?? null;
            if (is_string($acc) && $acc !== "") {
                $addFx("account", $acc, "increase", $amt, "cash");
            } else {
                $pushReason("MISSING_ACCOUNT");
            }
            $cat = $tx["categoryId"] ?? null;
            if (is_string($cat) && $cat !== "") {
                $addFx("expense_category", $cat, "decrease", $amt, "expense");
            } else {
                $pushReason("MISSING_CATEGORY");
            }
        }
    } elseif ($type === "transfer") {
        $eventType = "transfer";
        $from = $tx["accountId"] ?? "";
        $to = $tx["toAccountId"] ?? "";
        if (!is_string($from) || !is_string($to) || $from === "" || $to === "" || $from === $to) {
            $pushReason("INVALID_TRANSFER");
        } else {
            $addFx("account", $from, "decrease", $amt, "cash");
            $addFx("account", $to, "increase", $amt, "cash");
        }
