function household_sensitive_collections(): array {
    return ["households", "householdMembers", "householdPermissions"];
}

/**
 * Enforce: only household owner (or self-owned row) may mutate household* collections.
 * Members with role viewer cannot create/update/delete household config.
 */

function cloud_enforce_household_write(PDO $db, string $authUserId, string $collection, array $entity): void {
    if (!in_array($collection, household_sensitive_collections(), true)) {
        return;
    }

    if ($collection === "households") {
        // Creator owns the household row via userId already checked by caller.
        return;
    }

    $householdId = isset($entity["householdId"]) && is_string($entity["householdId"])
        ? $entity["householdId"]
        : "";
    if ($householdId === "") {
        throw new InvalidArgumentException("householdId is required for {$collection}");
    }

    // Load household owner from payload store
    $st = $db->prepare(
        "SELECT payload FROM cloud_collection_rows WHERE user_id = ? AND collection_name = 'households' AND entity_id = ? AND deleted_at IS NULL LIMIT 1"
    );
    $st->execute([$authUserId, $householdId]);
    $row = $st->fetch();
    if (!$row) {
        // Household may be owned by another user — deny cross-user writes
        throw new InvalidArgumentException("Household not found for authenticated user");
    }

    // Resolve caller's membership role
    $mst = $db->prepare(
        "SELECT payload FROM cloud_collection_rows WHERE user_id = ? AND collection_name = 'householdMembers' AND deleted_at IS NULL"
    );
    $mst->execute([$authUserId]);
    $role = "owner"; // default if no member rows yet (bootstrap)
    $found = false;
    while ($m = $mst->fetch()) {
        $payload = decode_payload($m["payload"]);
        if (($payload["householdId"] ?? "") === $householdId) {
            $found = true;
            $role = (string)($payload["role"] ?? "viewer");
            break;
        }
    }

    if ($found && $role === "viewer") {
        throw new InvalidArgumentException("Viewer role cannot modify household settings");
    }

    if ($collection === "householdPermissions") {
        if ($found && !in_array($role, ["owner", "partner"], true)) {
            throw new InvalidArgumentException("Only owner or partner can change household permissions");
        }
    }
}

function json_input(): array {
    $raw = file_get_contents("php://input");
    if ($raw === false || trim($raw) === "") {
        return [];
    }
    $decoded = json_decode($raw, true);
    if (!is_array($decoded)) {
        return [];
    }
    return $decoded;
}

function json_ok($data, int $status = 200): void {
    http_response_code($status);
    header("Content-Type: application/json; charset=utf-8");
    echo json_encode(["ok" => true, "data" => $data], JSON_UNESCAPED_SLASHES);
}

function json_error(string $message, int $status = 400, ?string $code = null): void {
    http_response_code($status);
    header("Content-Type: application/json; charset=utf-8");
    $payload = [
        "ok" => false,
        "error" => $message,
        "requestId" => (string)($_SERVER["REQUEST_ID"] ?? ""),
    ];
    if ($code !== null && $code !== "") {
        $payload["code"] = $code;
    }
    echo json_encode($payload, JSON_UNESCAPED_SLASHES);
}

function require_json_body(): array {
    $max = 1048576; // 1 MiB — keep in sync with cloud_max_entity_json_body_bytes() in cloud_payload.php
    $cl = (int)($_SERVER["CONTENT_LENGTH"] ?? 0);
    if ($cl > $max) {
        json_error("Request body too large", 413, "PAYLOAD_TOO_LARGE");
        exit;
    }
    $raw = file_get_contents("php://input");
    if ($raw === false || trim($raw) === "") {
        json_error("Invalid JSON payload", 400, "INVALID_JSON");
        exit;
    }
    if (strlen($raw) > $max) {
        json_error("Request body too large", 413, "PAYLOAD_TOO_LARGE");
        exit;
    }
    $decoded = json_decode($raw, true);
    if (!is_array($decoded) || json_last_error() !== JSON_ERROR_NONE) {
        json_error("Invalid JSON payload", 400, "INVALID_JSON");
        exit;
    }
    return $decoded;
}

function get_bearer_token(): ?string {
    $header = $_SERVER["HTTP_AUTHORIZATION"] ?? "";
    if (is_string($header) && str_starts_with($header, "Bearer ")) {
        return substr($header, 7);
    }
    $cookie = $_COOKIE["sv_auth"] ?? null;
    return is_string($cookie) && $cookie !== "" ? $cookie : null;
}

function cloud_money_max_abs_paise(): int {
    return (int)1e15;
}

function cloud_parse_money_input_to_paise(
    mixed $value,
    string $field = "amount",
    bool $allowZero = true,
    bool $allowRounding = true
): int {
    if ($value === null) {
        if ($allowZero) return 0;
        throw new InvalidArgumentException("{$field} is required");
    }
    if (is_bool($value) || (is_float($value) && !is_finite($value))) {
        throw new InvalidArgumentException("{$field} must be a valid rupee amount");
    }

    $raw = trim((string)$value);
    $raw = preg_replace('/(?:Rs\.?|INR|\x{20B9})/iu', '', $raw);
    $raw = str_replace([",", " "], "", $raw ?? "");
    if ($raw === "" || $raw === "." || $raw === "-" || $raw === "+") {
        if ($allowZero) return 0;
        throw new InvalidArgumentException("{$field} is required");
    }

    $negative = false;
    if ($raw[0] === "-" || $raw[0] === "+") {
        $negative = $raw[0] === "-";
        $raw = substr($raw, 1);
    }
    if ($negative) {
        throw new InvalidArgumentException("{$field} must be non-negative");
    }
    if (!preg_match('/^(\d+)(?:\.(\d+))?$/', $raw, $m)) {
        throw new InvalidArgumentException("{$field} must be a valid rupee amount");
    }

    $integerPart = ltrim($m[1], "0");
    if ($integerPart === "") $integerPart = "0";
    $fractionalPart = $m[2] ?? "";
    if (strlen($fractionalPart) > 2 && !$allowRounding) {
        throw new InvalidArgumentException("{$field} cannot have more than 2 decimal places");
    }

    if (strlen($integerPart) > 13) {
        throw new InvalidArgumentException("{$field} exceeds maximum allowed magnitude");
    }
    $paise = ((int)$integerPart) * 100;
    $firstTwo = substr($fractionalPart . "00", 0, 2);
    $paise += (int)$firstTwo;
    if ($allowRounding && strlen($fractionalPart) > 2 && (int)$fractionalPart[2] >= 5) {
        $paise += 1;
    }

    if ($paise === 0 && !$allowZero) {
        throw new InvalidArgumentException("{$field} must be greater than 0");
    }
    if (abs($paise) > cloud_money_max_abs_paise()) {
        throw new InvalidArgumentException("{$field} exceeds allowed magnitude");
    }
    return $paise;
}

function cloud_try_money_input_to_paise(mixed $value, string $field = "amount", bool $allowZero = true, bool $allowRounding = true): ?int {
    try {
        return cloud_parse_money_input_to_paise($value, $field, $allowZero, $allowRounding);
    } catch (Throwable) {
        return null;
    }
}

function cloud_paise_to_rupee_amount(int $paise): float {
    return round($paise) / 100;
}

function cloud_validate_integer_paise_field(array $entity, string $field): void {
    if (!array_key_exists($field, $entity)) {
        return;
    }
    $v = $entity[$field];
    if ($v === null) {
        return;
    }
    if (!is_int($v) && !(is_float($v) && floor($v) === $v)) {
        throw new InvalidArgumentException("Field {$field} must be an integer paise value");
    }
    $iv = (int)$v;
    if ($iv < 0) {
        throw new InvalidArgumentException("Field {$field} must be non-negative");
    }
    if (abs($iv) > cloud_money_max_abs_paise()) {
        throw new InvalidArgumentException("Field {$field} exceeds allowed magnitude");
    }
}

function cloud_validate_money_fields(string $collection, array $entity): void {
    switch ($collection) {
        case "transactions":
            cloud_validate_integer_paise_field($entity, "amountPaise");
            break;
        case "accounts":
            cloud_validate_integer_paise_field($entity, "openingBalancePaise");
            break;
        case "cards":
            cloud_validate_integer_paise_field($entity, "creditLimitPaise");
            break;
        case "budgets":
            cloud_validate_integer_paise_field($entity, "limitPaise");
            break;
        case "loans":
            cloud_validate_integer_paise_field($entity, "principalPaise");
            cloud_validate_integer_paise_field($entity, "emiPaise");
            cloud_validate_integer_paise_field($entity, "outstandingPrincipalPaise");
            break;
        case "emis":
            cloud_validate_integer_paise_field($entity, "amountPaise");
            cloud_validate_integer_paise_field($entity, "amountPaidPaise");
            cloud_validate_integer_paise_field($entity, "principalComponentPaise");
            cloud_validate_integer_paise_field($entity, "interestComponentPaise");
            break;
        case "goals":
            cloud_validate_integer_paise_field($entity, "targetAmountPaise");
            cloud_validate_integer_paise_field($entity, "savedAmountPaise");
            break;
        case "udhari":
            cloud_validate_integer_paise_field($entity, "amountPaise");
            cloud_validate_integer_paise_field($entity, "amountSettledPaise");
            break;
        case "udhariSettlements":
        case "goalContribs":
        case "savingsContribs":
        case "recurringRules":
            cloud_validate_integer_paise_field($entity, "amountPaise");
            break;
        case "investments":
            cloud_validate_integer_paise_field($entity, "amountPaise");
            cloud_validate_integer_paise_field($entity, "totalContributedPaise");
            break;
        default:
            break;
    }
}

/** Best-effort primary amount for cloud_collection_rows.amount_paise */

function cloud_entity_primary_amount_paise(string $collection, array $entity): ?int {
    if (isset($entity["amountPaise"]) && is_numeric($entity["amountPaise"])) {
        return (int)$entity["amountPaise"];
    }
    switch ($collection) {
        case "transactions":
            return array_key_exists("amount", $entity) ? cloud_try_money_input_to_paise($entity["amount"], "amount") : null;
        case "accounts":
            if (isset($entity["openingBalancePaise"]) && is_numeric($entity["openingBalancePaise"])) {
                return (int)$entity["openingBalancePaise"];
            }
            return array_key_exists("openingBalance", $entity)
                ? cloud_try_money_input_to_paise($entity["openingBalance"], "openingBalance")
                : null;
        case "cards":
            if (isset($entity["creditLimitPaise"]) && is_numeric($entity["creditLimitPaise"])) {
                return (int)$entity["creditLimitPaise"];
            }
            return array_key_exists("creditLimit", $entity)
                ? cloud_try_money_input_to_paise($entity["creditLimit"], "creditLimit")
                : null;
        case "budgets":
            if (isset($entity["limitPaise"]) && is_numeric($entity["limitPaise"])) {
                return (int)$entity["limitPaise"];
            }
            return array_key_exists("amount", $entity) ? cloud_try_money_input_to_paise($entity["amount"], "amount") : null;
        case "loans":
            if (isset($entity["principalPaise"]) && is_numeric($entity["principalPaise"])) {
                return (int)$entity["principalPaise"];
            }
            return array_key_exists("principal", $entity)
                ? cloud_try_money_input_to_paise($entity["principal"], "principal")
                : null;
        case "emis":
            if (isset($entity["amountPaise"]) && is_numeric($entity["amountPaise"])) {
                return (int)$entity["amountPaise"];
            }
            return array_key_exists("amount", $entity) ? cloud_try_money_input_to_paise($entity["amount"], "amount") : null;
        case "goals":
            if (isset($entity["targetAmountPaise"]) && is_numeric($entity["targetAmountPaise"])) {
                return (int)$entity["targetAmountPaise"];
            }
            return array_key_exists("targetAmount", $entity)
                ? cloud_try_money_input_to_paise($entity["targetAmount"], "targetAmount")
                : null;
        case "udhari":
            if (isset($entity["amountPaise"]) && is_numeric($entity["amountPaise"])) {
                return (int)$entity["amountPaise"];
            }
            return array_key_exists("amount", $entity) ? cloud_try_money_input_to_paise($entity["amount"], "amount") : null;
        case "goalContribs":
        case "udhariSettlements":
        case "savingsContribs":
        case "recurringRules":
            if (isset($entity["amountPaise"]) && is_numeric($entity["amountPaise"])) {
                return (int)$entity["amountPaise"];
            }
            return array_key_exists("amount", $entity) ? cloud_try_money_input_to_paise($entity["amount"], "amount") : null;
        case "investments":
            if (isset($entity["amountPaise"]) && is_numeric($entity["amountPaise"])) {
                return (int)$entity["amountPaise"];
            }
            return array_key_exists("amount", $entity) ? cloud_try_money_input_to_paise($entity["amount"], "amount") : null;
        default:
            return null;
    }
}

function financial_mutation_table_ready(PDO $db): bool {
    static $ready = null;
    if ($ready !== null) return $ready;
    try {
        $db->query("SELECT 1 FROM financial_mutation_keys LIMIT 0");
        $ready = true;
        return true;
    } catch (Throwable) {
        // Auto-provision for cert/dev environments so idempotency is enforceable.
        try {
            $db->exec(
                "CREATE TABLE IF NOT EXISTS financial_mutation_keys (
                  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
                  user_id VARCHAR(64) NOT NULL,
                  mutation_id VARCHAR(128) NOT NULL,
                  collection_name VARCHAR(64) NOT NULL,
                  entity_id VARCHAR(64) NOT NULL,
                  operation VARCHAR(32) NOT NULL DEFAULT 'create',
                  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                  PRIMARY KEY (id),
                  UNIQUE KEY uq_fin_mut_user_mutation (user_id, mutation_id),
                  KEY idx_fin_mut_entity (user_id, collection_name, entity_id)
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
            );
            $ready = true;
            return true;
        } catch (Throwable) {
            $ready = false;
            return false;
        }
    }
}

/**
 * @return array{hit:bool,entityId:?string}|null null if table missing (soft skip)
 */

function financial_mutation_lookup(PDO $db, string $userId, string $mutationId): ?array {
    if ($mutationId === "" || !financial_mutation_table_ready($db)) {
        return null;
    }
    $st = $db->prepare(
        "SELECT entity_id FROM financial_mutation_keys WHERE user_id = ? AND mutation_id = ? LIMIT 1"
    );
    $st->execute([$userId, $mutationId]);
    $row = $st->fetch();
    if (!$row) {
        return ["hit" => false, "entityId" => null];
    }
    return ["hit" => true, "entityId" => (string)$row["entity_id"]];
}

function financial_mutation_record(
    PDO $db,
    string $userId,
    string $mutationId,
    string $collection,
    string $entityId,
    string $operation = "create"
): void {
    if ($mutationId === "" || !financial_mutation_table_ready($db)) {
        return;
    }
    try {
        $st = $db->prepare(
            "INSERT INTO financial_mutation_keys (user_id, mutation_id, collection_name, entity_id, operation)
             VALUES (?, ?, ?, ?, ?)"
        );
        $st->execute([$userId, $mutationId, $collection, $entityId, $operation]);
    } catch (Throwable $e) {
        // Unique race — caller should re-lookup
        throw $e;
    }
}

